                                {cons.hasReminder && (
                                    <div className="text-xs font-bold text-indigo-500 flex items-center gap-1 bg-indigo-50 px-2 py-1 rounded-md w-max border border-indigo-100">
                                        <Bell size={12} /> {cons.reminder || 'Lembrete'}
                                    </div>
                                )}
                            </div>
                         </div>

                         <div className="flex items-center gap-6 w-full md:w-auto justify-between">
                            <div className="text-right">
                               <div className="text-xs text-gray-400">Comissão</div>
                               <div className="font-bold text-teal-600">{formatMoney(cons.doctorCommission)} MT</div>
                            </div>

                            <div className="flex gap-1">
                               <button 
                                 onClick={() => handleEdit(cons)} 
