import { Budget, BudgetPhase, BudgetProcedure, DbPrice } from '../types';
import { ArrowLeft, Plus, Save, Trash2, ChevronDown, ChevronUp, Printer, Search, X, Loader2, AlertCircle } from 'lucide-react';
import { DentalQuoteTemplate } from '../components/DentalQuoteTemplate';

const DEFAULT_PHASES = [
  "Fase 1: Consulta e realização de exames para estudo de caso",
  "Fase 2: Montagem do aparelho fixo",
  "Fase 3: Controlos para activação e manutenção do aparelho fixo",
  "Fase 4: Remoção e confeção do aparelho de contenção"
];

// Helper to print manually
const printBudget = (budget: Budget, patientPhone: string | undefined, onAfterPrint?: () => void) => {
  const iframe = document.createElement('iframe');
  iframe.style.display = 'none';
  document.body.appendChild(iframe);

  const doc = iframe.contentWindow?.document;
  if (!doc) return;

  doc.open();
  doc.write(`
    <!DOCTYPE html>
    <html lang="pt-PT">
      <head>
        <title>Orçamento ${budget.number}</title>
        <meta charset="UTF-8" />
        <meta name="viewport" content="width=device-width, initial-scale=1.0" />
        <script src="https://cdn.tailwindcss.com"></script>
        <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap" rel="stylesheet">
        <style>
           body { font-family: 'Inter', sans-serif; -webkit-print-color-adjust: exact; print-color-adjust: exact; margin: 0; padding: 0; background: white; }
           @page { margin: 0; }
        </style>
      </head>
      <body>
        <div id="print-mount"></div>
      </body>
    </html>
  `);
  doc.close();

  setTimeout(() => {
      const mountNode = doc.getElementById('print-mount');
      if (mountNode) {
          const root = createRoot(mountNode);
          const logoUrl = window.location.origin + "/logo.png";

          // Passa o telefone do paciente para o template
          root.render(<DentalQuoteTemplate budget={budget} logoUrl={logoUrl} patientPhone={patientPhone} />);

          setTimeout(() => {
              const originalTitle = document.title;
              const safeDate = budget.date.replace(/-/g, '');
              const safeName = budget.patientName.replace(/[^a-zA-Z0-9]/g, '_');
              const safeStatus = budget.status === 'rascunho' ? 'RASCUNHO' : 'FINAL';

              const fileName = `ORC-${safeDate}-${safeName}-${safeStatus}`;

              document.title = fileName;
              if (iframe.contentDocument) iframe.contentDocument.title = fileName;

              iframe.contentWindow?.focus();
              iframe.contentWindow?.print();

              document.title = originalTitle;

              if (onAfterPrint) onAfterPrint();

              setTimeout(() => {
                 if (document.body.contains(iframe)) {
                   document.body.removeChild(iframe);
                 }
              }, 10000);
          }, 1000); 
      }
  }, 500);
};

