  useEffect(() => {
    if (id && id !== 'new') {
       const existing = budgets.find(b => b.id === id);
       if (existing) {
          setDate(existing.date);
          setSelectedPatientId(existing.patientId);
          setPatientSearchTerm(existing.patientName);
          setStatus(existing.status);
          setPhases(existing.phases);

