        <div className="bg-slate-800 p-4 rounded-xl shadow-xl border border-slate-700 z-50 max-w-[240px]">
          <div className="flex items-center gap-2 mb-2 pb-2 border-b border-slate-700">
             <div className="w-3 h-3 rounded-full shadow-sm" style={{ backgroundColor: data.color }}></div>
             <span className="font-bold text-slate-100 text-sm">{data.name}</span>
          </div>
          <div className="mb-2">
             <span className="text-2xl font-bold text-white tracking-tight">{formatMoney(data.value)}</span>
          </div>
          <p className="text-[11px] text-slate-400 leading-relaxed">
             Corresponde a <strong className="text-teal-400">{percent}%</strong> de toda a tua facturação neste período.
          </p>
        </div>
      );
    }
    return null;
  };

  return (
    <div className="pb-40 pt-6 px-5 max-w-lg mx-auto space-y-6 bg-gray-50 min-h-screen font-sans">

      <div>
        <h1 className="text-xl font-semibold text-slate-800 mb-1">Relatórios</h1>
        <p className="text-xs text-gray-500">Gestão e Performance</p>
      </div>

      {/* Filtros */}
      <div className="bg-[#FAFAFA] p-4 rounded-2xl border border-gray-200 shadow-sm flex flex-col gap-4">
        <div className="flex flex-col md:flex-row justify-between md:items-center gap-4">
           <div className="bg-gray-200/50 p-1 rounded-xl flex shrink-0 w-full md:w-auto self-start">
              <button 
                onClick={() => setFilterType('month')}
