                   <Tooltip cursor={{fill: 'transparent'}} content={<CustomTooltipTop5 />} />
                   <Bar dataKey="value" radius={[0, 4, 4, 0]} barSize={18}>
                     {reportData.top5.map((entry, index) => (
                       <Cell key={`cell-${index}`} fill={entry.color} />
