        if (error.message === 'Invalid login credentials') {
           setErrorMsg('Email ou password incorrectos.');
        } else {
           setErrorMsg(error.message);
        }
      }
    } catch (err) {
      setErrorMsg('Ocorreu um erro inesperado.');
    } finally {
      setIsSubmitting(false);
    }
  };

